import numpy as np

def feature(costs, new_cover, sizes, covers, total):
    """Newly covered element count per candidate, divided by the max over candidates, plus a tiny tie-break by full size."""
    v = new_cover.astype(float)
    m = v.max()
    if m <= 0:
        return np.zeros_like(v)
    base = v / m
    # tiny secondary term: among equal new_cover, prefer larger full sets (more overlap absorbed)
    s = sizes.astype(float)
    sm = s.max()
    if sm <= 0:
        return base
    return base + 1e-3 * (s / sm)

import numpy as np

def feature(costs, new_cover, sizes, covers, total):
    """Negative cost per newly covered element, inflated by the already-covered share of the set."""
    covfrac = (sizes - new_cover) / np.maximum(sizes, 1)
    v = (costs.astype(float) / np.maximum(new_cover, 1)) * (1.0 + covfrac)
    rng = v.max() - v.min()
    if rng < 1e-12:
        return np.zeros_like(v)
    return -(v - v.min()) / rng

import numpy as np

def feature(costs, new_cover, sizes, covers, total):
    """Exclusive newly-covered elements beyond the strongest rival (max new_cover) set, normalised by max new_cover."""
    g = new_cover.astype(float)
    k = len(g)
    if k == 1:
        return np.zeros(1)
    j = int(np.argmax(g))
    shared = (covers & covers[j][None, :]).sum(axis=1).astype(float)
    irr = np.maximum(g - shared, 0.0)
    return irr / np.maximum(g.max(), 1.0)
